import{_ as t,o,c as s,a2 as a}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"Desktop Shell","description":"","frontmatter":{"epic":9,"title":"Desktop Shell","status":"✅ Complete","scope":"desktop","sourceUrl":"https://github.com/sovereignfs/sovereign-edge/blob/main/docs/epics/desktop/shell.md"},"headers":[],"relativePath":"sovereign-edge/epics/desktop/shell.md","filePath":"sovereign-edge/epics/desktop/shell.md"}'),i={name:"sovereign-edge/epics/desktop/shell.md"};function r(l,e,n,c,h,d){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="epic-desktop-shell" tabindex="-1">Epic: Desktop Shell <a class="header-anchor" href="#epic-desktop-shell" aria-label="Permalink to &quot;Epic: Desktop Shell&quot;">​</a></h1><blockquote><p>Which technology <code>apps/desktop</code> is built on. A one-task epic: once decided, everything else desktop needs lives in <a href="./core-port.html">Desktop Core Port</a>, not here.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Per the developer&#39;s decision, desktop as a whole is deliberately deferred — see <a href="./core-port.html">Desktop Core Port</a> for the epic holding the actual implementation work, sequenced against Phase 1/2/3 separately from this one. This epic exists only to hold the shell-technology decision itself, and closes once that decision is recorded.</p><p><strong>Sequencing note:</strong> this epic&#39;s own dependency (&quot;Mobile MVP (Phase 1) shipped&quot;) was deliberately pulled forward ahead of task 0.1.20 (store release setup, the one still-open Phase 1 item) on the developer&#39;s explicit instruction — see <a href="./../../research/0010-desktop-shell-technology.html#note-on-sequencing">research 0010</a>.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h4 id="✅-9-1-—-desktop-shell-technology-spike" tabindex="-1">✅ 9.1 — Desktop shell technology spike <a class="header-anchor" href="#✅-9-1-—-desktop-shell-technology-spike" aria-label="Permalink to &quot;✅ 9.1 — Desktop shell technology spike&quot;">​</a></h4><p><strong>Goal:</strong> Decide the desktop client&#39;s technology once there&#39;s a reason to build it.</p><p><strong>Deliverables:</strong></p><ul><li>A short research pass (candidate: a follow-up research doc) comparing Tauri, Electron, and any RN-desktop option against this app&#39;s specific needs — native <code>llama.cpp</code> bindings, Tier 3 OS integration surface, install size.</li></ul><p><strong>Dependencies:</strong> Mobile MVP (Phase 1) shipped.</p><p><strong>Review checklist:</strong></p><ul><li>A decision is recorded (mirroring this repo&#39;s research-doc convention) before any desktop implementation task starts.</li></ul><p><strong>Decided: Tauri v2.</strong> Full reasoning, options considered, and the alternatives&#39; rejection rationale in <a href="./../../research/0010-desktop-shell-technology.html">research 0010</a>. In short: <code>llama.rn</code> (the mobile inference binding) has no macOS/Windows support and no signaled path to it, ruling out a React Native desktop shell without giving up the one thing that would have recommended it (reusing <code>packages/mobile-ui</code> directly); Tauri and Electron both have real, maintained Rust/Node <code>llama.cpp</code> bindings, and Tauri wins on install size and on its default-deny capabilities model, which is the closest structural match to this project&#39;s existing per-connector permission architecture. Electron&#39;s advantage — no new language, since the stack is TypeScript throughout today — was the strongest point on its side and is recorded as the real cost of this decision, not dismissed.</p><h2 id="related-docs" tabindex="-1">Related Docs <a class="header-anchor" href="#related-docs" aria-label="Permalink to &quot;Related Docs&quot;">​</a></h2><ul><li><a href="./../../../CONCEPT.html">CONCEPT.md</a></li><li><a href="./../../research/0001-concept-and-connector-architecture.html">research 0001</a></li><li><a href="./../../research/0010-desktop-shell-technology.html">research 0010</a> — the shell technology decision (task 9.1)</li><li><a href="./core-port.html">Desktop Core Port</a> — epic 12, the desktop work this decision unblocks</li></ul>',16)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
